/* MUTANT: one refusal broken on purpose. The gate MUST go red against this
 * file. Generated by mut/make.py; never edited by hand.
 */
/* <ov-authority> - who is flying each system, and who acts next.
 *
 * For aegis, machina, antiseptic, industrial and holo. Drawn as LANES OVER
 * TIME: one lane for each kind of controller (CREW, REMOTE, AUTO) and a
 * hatched NO ONE lane beneath them, a NOW line, the recent past to its left
 * and what is coming to its right. Each system is a bar in the lane of whoever
 * holds it; a handover is the bar stepping between lanes. Next actions are
 * markers ahead of NOW in their owner's lane, and a step that waits on a
 * condition rather than a time sits in the ON TRIGGER column at the edge.
 *
 *   <ov-authority label="VEHICLE" src="models/authority-docking.json"></ov-authority>
 *   el.picture = {
 *     mode: 'operational',
 *     systems: [{
 *       id: 'attitude', label: 'ATTITUDE', control: 'auto', level: 'full', state: 'running',
 *       active: 'HOLD INERTIAL', armed: 'TRACK TARGET',
 *       next: { action: 'TRACK TARGET', owner: 'auto', trigger: 'RANGE < 200 m' },
 *     }],
 *   };
 *   el.acknowledge('attitude', 'CDR');   // clears a kept unannounced change
 *
 * `past` and `ahead` (seconds, default 60 and 300) set how much of the axis
 * each side of NOW covers; each side is linear and printed with its own ticks.
 *
 * ── THE REFUSAL ───────────────────────────────────────────────────────────
 *
 * 🔴 NOBODY IS FLYING A SYSTEM UNTIL SOMETHING SAYS WHO IS. A system with no
 * declared source of control is drawn in the NO ONE lane and reads UNDECLARED,
 * never a default AUTO: NASA-STD-3001 Vol 2 App. F.6.2, "Source of control
 * should be clearly indicated (Autonomous system vs Crew software commanding
 * vs Crew manual commanding vs Remote operator commanding) for all systems".
 *
 * And five that follow from it:
 *
 * 1. A NEXT ACTION WITH NO OWNER IS NOT THE AUTOMATION'S. Its marker sits in
 *    NO ONE and reads OWNER NOT STATED. [V2 10164]: "Automated systems shall
 *    indicate whether a human operator or system is expected to perform a
 *    particular operation at a specific time", because close calls came from
 *    a person who did not know it was theirs. A crew action past its time is
 *    pinned at NOW, OVERDUE, with a tail back to when it was due.
 * 2. A STEP BEHIND AN INHIBITED TRIGGER IS NOT WAITING. It leaves the ON
 *    TRIGGER column, where its gate is drawn broken, and sits at NOW reading
 *    WILL RUN AT ONCE. In a Starliner simulation "when the desired step was
 *    inhibited, the subsequent commands executed right away, unexpectedly,
 *    until the sequencer hit the next unmet trigger condition" (Dempsey et
 *    al., SpaceOps 2021). The drawing is INFERRED from that account; the paper
 *    names the failure, not a display.
 * 3. A HANDOVER IS A STEP, AND AN UNANNOUNCED ONE IS KEPT. Every change of
 *    control or active mode is labelled for ten seconds with what it came
 *    FROM. One the vehicle did not announce ([V2 10162]: "notify the human
 *    operator of mode changes") draws its step in the alarm form and stays
 *    marked UNANNOUNCED until someone named acknowledges it.
 * 4. SELECTED IS NOT ARMED, AND AN AUTOMATIC REVERSION IS NOT A REPLACEMENT.
 *    An armed mode runs ahead of NOW as a dashed stub; one only selected is
 *    dotted and reads SELECTED, NOT ARMED (FAA AC 25.1329-1C: "Mode selector
 *    switch position or status is not acceptable as the sole means of mode
 *    annunciation"). A reversion is named REVERTED FROM the old mode.
 * 5. SIMULATION, TEST AND OPERATIONS ARE NEVER MIXED UNSEEN. The picture's
 *    mode is always printed; with none the element reads MODE NOT STATED, and
 *    a system in a different mode from the picture has its bar refused
 *    (hatched) and says so ([V2 10153]).
 *
 * ⚠️ AHEAD OF NOW IS NOT KNOWN. A bar is solid only where it was reported;
 * past NOW it continues as a thin dotted line, which says "nothing has said
 * this will change", not "this will hold".
 *
 * With `max-age`, a picture not updated for that long is STALE with its age,
 * its NOW line goes dashed, and its next-action times are no longer counted.
 *
 * Drawn on each update and at most once a second while on screen. Nothing
 * asks for an animation frame.
 */

import { define, watchSeen, isSeen, whenArrived } from '../../../src/ov-core.js';
import '../../../src/ov-source.js';

const CONTROL = {
  auto: 'AUTO',
  'crew-software': 'CREW SOFTWARE',
  'crew-manual': 'CREW MANUAL',
  remote: 'REMOTE',
};
const OWNER = { auto: 'AUTO', crew: 'CREW', remote: 'REMOTE' };
const LEVEL = { full: 'FULL', partial: 'PARTIAL', none: 'NONE' };
const STATE = { running: 'RUNNING', paused: 'PAUSED', faulted: 'FAULTED', overridden: 'OVERRIDDEN', stopped: 'STOPPED' };
const MODES = { operational: 'OPERATIONAL', test: 'TEST', simulation: 'SIMULATION' };
const BOX_MS = 10_000;

// The lanes, top to bottom, and which lane a controller or an owner lives in.
const LANES = ['crew', 'remote', 'auto', 'none'];
const LANE_WORD = { crew: 'CREW', remote: 'REMOTE', auto: 'AUTO', none: 'NO ONE' };
const laneOf = (control) => (control === 'crew-software' || control === 'crew-manual' ? 'crew' : control || 'none');
// NOW sits here along the time field, as a fraction of its width.
export const X_NOW = 0.45;
const SLOT = 34;       // px per system in a lane
// ⚠️ UNDER THIS WIDTH THE TEXT CANNOT SIT EITHER SIDE OF NOW. Measured on the
// demo: a 343px field cut every name behind NOW off at its left edge. Narrow,
// the name, the modes and the state each take a line from the left, and a
// system's slot is taller to hold them.
const NARROW_W = 560;
const SLOT_NARROW = 58;
const LANE_PAD = 6;   // px above and below the slots
const EMPTY = 20;     // px for a lane with nobody in it

const esc = (s) => String(s).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const setText = (el, t) => { if (el && el.textContent !== t) el.textContent = t; };
const setAttr = (el, k, v) => {
  if (!el) return;
  if (v === null) { if (el.hasAttribute(k)) el.removeAttribute(k); } else if (el.getAttribute(k) !== v) el.setAttribute(k, v);
};
const setStyle = (el, k, v) => { if (el && el.style.getPropertyValue(k) !== v) el.style.setProperty(k, v); };
const word = (v) => (typeof v === 'string' && v.trim() ? v.trim().toUpperCase() : null);
const pct = (f) => `${(Math.max(0, Math.min(1, f)) * 100).toFixed(2)}%`;
const f1 = (v) => v.toFixed(1);

/* Seconds -> "12s", "4m 10s", "3h 05m". */
export function span(s) {
  const n = Math.max(0, Math.floor(s));
  if (n < 60) return `${n}s`;
  if (n < 3600) return `${Math.floor(n / 60)}m ${String(n % 60).padStart(2, '0')}s`;
  return `${Math.floor(n / 3600)}h ${String(Math.floor(n / 60) % 60).padStart(2, '0')}m`;
}
const short = (s) => (s < 60 ? `${Math.round(s)}s` : s % 60 ? span(s) : `${s / 60}m`);

let serial = 0;

class OvAuthority extends HTMLElement {
  static observedAttributes = ['label', 'src', 'source', 'max-age', 'past', 'ahead'];

  /* Our clock, in epoch ms. Replaceable so a test can drive time. */
  static now = () => Date.now();

  constructor() {
    super();
    this._sys = new Map();       // id -> kept state: { control, active, due, changes, hist }
    this._picture = undefined;
    this._at = null;
    this._malformed = 0;
    this._rows = new Map();
    this._rowKey = null;
    this._uid = `ov-authority-${++serial}`;
  }

  connectedCallback() {
    if (!this._built) this.build();
    this.fetchSrc();
    this.bindSource();
    this.render();
    // 🔴 A LIVE LOOP WAITS FOR THE PAGE: ov-core holds timers until arrival.
    if (!this._unarrive) this._unarrive = whenArrived(() => this.startTicking());
    if (!this._unwatch) this._unwatch = watchSeen(this, () => this.render());
  }

  startTicking() {
    if (this._timer || !this.isConnected) return;
    this._timer = setInterval(() => { if (isSeen(this)) this.render(); }, 1000);
  }

  disconnectedCallback() {
    clearInterval(this._timer);
    this._timer = 0;
    if (this._unarrive) this._unarrive();
    this._unarrive = null;
    if (this._unwatch) this._unwatch();
    this._unwatch = null;
    if (this.unsub) this.unsub();
    this.unsub = null;
  }

  attributeChangedCallback(name) {
    if (!this._built) return;
    if (name === 'src') { this.fetchSrc(); return; }
    if (name === 'source') this.bindSource();
    this.render();
  }

  /* 🔴 A FETCH THAT FAILS LEAVES NO PICTURE, NOT A STALE ONE. */
  async fetchSrc() {
    const src = this.getAttribute('src');
    if (!src) return;
    let data = null;
    try {
      const r = await fetch(src);
      if (!r.ok) throw new Error(String(r.status));
      data = await r.json();
    } catch {
      data = null;
    }
    if (this.getAttribute('src') !== src) return;
    this.picture = data;
  }

  bindSource() {
    if (this.unsub) this.unsub();
    this.unsub = null;
    const name = this.getAttribute('source');
    if (!name || !window.Overscan?.subscribe) return;
    this.unsub = window.Overscan.subscribe(name, (p) => { if (p !== null && p !== undefined) this.picture = p; });
  }

  /* ---- the door ------------------------------------------------------- */

  set picture(p) { this.update(p); }
  get picture() { return this._picture; }

  update(p) {
    const now = OvAuthority.now();
    this._picture = p && typeof p === 'object' ? p : null;
    this._at = this._picture ? now : null;
    this._malformed = 0;
    const seen = new Set();
    for (const s of this._picture?.systems ?? []) {
      if (!s || typeof s !== 'object' || typeof s.id !== 'string' || !s.id || seen.has(s.id)) { this._malformed += 1; continue; }
      seen.add(s.id);
      this.observe(s, now);
    }
    for (const id of [...this._sys.keys()]) if (!seen.has(id)) this._sys.delete(id);
    this.render();
  }

  /* Compares a system's report with the last one and keeps what changed. */
  observe(s, now) {
    const k = this._sys.get(s.id) || { control: undefined, active: undefined, due: null, dueKey: null, changes: [], unannounced: null, hist: [] };
    const control = Object.hasOwn(CONTROL, s.control) ? s.control : null;
    const active = word(s.active);
    const first = k.control === undefined;
    const say = [];
    if (first) k.hist.push({ at: now, control, announced: true });
    if (!first) {
      for (const [what, from, to, show] of [
        ['control', k.control, control, (v) => (v ? CONTROL[v] : 'UNDECLARED')],
        ['mode', k.active, active, (v) => v || 'NO MODE'],
      ]) {
        if (from === to) continue;
        const announced = s.announced === true;
        const reverted = what === 'mode' && s.reversion === true;
        const change = { what, from: show(from), to: show(to), at: now, announced, reverted };
        k.changes.push(change);
        if (k.changes.length > 8) k.changes.shift();
        if (what === 'control') k.hist.push({ at: now, control: to, announced });
        const label = word(s.label) || s.id.toUpperCase();
        if (!announced) {
          // Kept as a list: control and mode can both change unannounced in
          // one report, and keeping only the last would hide the other.
          (k.unannounced ||= []).push(change);
          say.push(`${label}: unannounced ${what} change, ${change.from} to ${change.to}`);
        }
        this.dispatchEvent(new CustomEvent('ov:authority', {
          bubbles: true, detail: { system: s.id, what, from: change.from, to: change.to, announced, reverted },
        }));
      }
    }
    if (k.hist.length > 32) k.hist.splice(0, k.hist.length - 32);
    k.control = control;
    k.active = active;
    // A next action's time arrives relative (`in` seconds) and is fixed to our
    // clock once, so a repeated picture does not keep pushing it back.
    const n = s.next;
    const key = n ? `${n.action}|${n.owner}|${n.in}|${n.trigger}` : null;
    if (key !== k.dueKey) {
      k.dueKey = key;
      k.due = n && Number.isFinite(Number(n.in)) ? now + Number(n.in) * 1000 : null;
    }
    this._sys.set(s.id, k);
    for (const t of say) this.say(t);
  }

  /* Only a named person clears a kept unannounced change. */
  acknowledge(id, by) {
    const k = this._sys.get(id);
    if (!k?.unannounced) return false;
    if (!by || !String(by).trim()) {
      this.say(`${id} acknowledgement refused, it must say who`);
      return false;
    }
    k.unannounced = null;
    for (const h of k.hist) h.announced = true;
    this.render();
    return true;
  }

  /* ---- what is true right now ----------------------------------------- */

  // Not `slot()`: every element already has a native `slot` property, and
  // tools/api.py refuses a method that shadows one.
  slotH() { return this._narrow ? SLOT_NARROW : SLOT; }

  /* Read by literal name, so tools/api.py can list both attributes. */
  pastS() {
    const v = Number(this.getAttribute('past'));
    return this.hasAttribute('past') && Number.isFinite(v) && v > 0 ? v : 60;
  }

  aheadS() {
    const v = Number(this.getAttribute('ahead'));
    return this.hasAttribute('ahead') && Number.isFinite(v) && v > 0 ? v : 300;
  }

  /* Where time t sits along the field, 0..1: the past side and the ahead side
   * are each linear, and NOW is X_NOW. */
  xOf(t, now) {
    const past = this.pastS() * 1000;
    const ahead = this.aheadS() * 1000;
    return t <= now ? X_NOW * (1 - (now - t) / past) : X_NOW + (1 - X_NOW) * ((t - now) / ahead);
  }

  rows(now) {
    const pic = this._picture;
    const picMode = pic && Object.hasOwn(MODES, pic.mode) ? pic.mode : null;
    const maxAge = Number(this.getAttribute('max-age'));
    const stale = this._at !== null && Number.isFinite(maxAge) && maxAge > 0 && now - this._at > maxAge * 1000;
    return (pic?.systems ?? []).filter((s) => s && this._sys.has(s.id)).map((s) => {
      const k = this._sys.get(s.id);
      const r = {
        id: s.id, label: word(s.label) || s.id.toUpperCase(),
        control: k.control, lane: laneOf(k.control), level: Object.hasOwn(LEVEL, s.level) ? s.level : null,
        state: Object.hasOwn(STATE, s.state) ? s.state : null,
        active: k.active, armed: word(s.armed), selected: word(s.selected),
        modeFault: null, next: null, box: null, unannounced: k.unannounced, by: s.by || null, hist: k.hist,
      };
      if (s.mode !== undefined && picMode && s.mode !== picMode) {
        r.modeFault = `${Object.hasOwn(MODES, s.mode) ? MODES[s.mode] : String(s.mode).toUpperCase()} INSIDE ${MODES[picMode]}`;
      }
      // 🔴 EVERY CHANGE FROM THE LATEST REPORT, NOT ONLY THE LAST ONE. A crew
      // member taking a system by hand changes its control and its mode in one
      // report, and boxing only the mode hid the handover itself.
      const last = k.changes[k.changes.length - 1];
      if (last && now - last.at < BOX_MS) r.box = k.changes.filter((c) => c.at === last.at);
      const n = s.next;
      if (n && typeof n === 'object') {
        const owner = Object.hasOwn(OWNER, n.owner) ? n.owner : null;
        // where: 'time' on the axis at `x`, 'now' pinned at NOW, 'gate' in the
        // ON TRIGGER column, 'none' with nothing to place it by.
        const nx = { action: word(n.action) || 'ACTION NOT NAMED', owner, lane: owner || 'none', when: '', tone: 'ok', where: 'none', x: null, dueX: null, trigger: word(n.trigger), inhibited: false };
        if (false) {  // MUTANT: an inhibited trigger still holds the step
          nx.when = `WILL RUN AT ONCE · TRIGGER ${word(n.trigger)} INHIBITED`;
          nx.tone = 'bad';
          nx.where = 'now';
          nx.inhibited = true;
        } else if (n.trigger) {
          nx.when = `ON ${word(n.trigger)}`;
          nx.where = 'gate';
        } else if (k.due !== null) {
          const left = (k.due - now) / 1000;
          if (stale) { nx.when = `WAS DUE IN ${span(left)} AT LAST REPORT`; nx.tone = 'note'; nx.where = 'none'; }
          else if (left >= 0) { nx.when = `IN ${span(left)}`; nx.where = 'time'; nx.x = this.xOf(k.due, now); }
          else {
            nx.when = owner === 'crew' ? `OVERDUE ${span(-left)}` : `DUE ${span(-left)} AGO`;
            nx.tone = 'bad';
            nx.where = 'now';
            nx.dueX = this.xOf(k.due, now);
          }
        } else {
          nx.when = 'NO TIME OR TRIGGER STATED';
          nx.tone = 'note';
        }
        if (!owner) nx.tone = 'bad';
        r.next = nx;
      }
      return r;
    });
  }

  get report() {
    const now = OvAuthority.now();
    const pic = this._picture;
    return {
      mode: pic && Object.hasOwn(MODES, pic.mode) ? pic.mode : null,
      systems: this.rows(now).map(({ hist, ...r }) => r),
      malformed: this._malformed,
      age: this._at === null ? null : (now - this._at) / 1000,
    };
  }

  /* Which systems appear in each lane in the visible window: by their bar
   * now, by any bar still in the past window, or by a next-action marker.
   * Returns { lane: [ids] } and each lane's top and height in px. */
  layout(rows, now) {
    const past = this.pastS() * 1000;
    const occ = Object.fromEntries(LANES.map((l) => [l, []]));
    const add = (lane, id) => { if (!occ[lane].includes(id)) occ[lane].push(id); };
    for (const r of rows) {
      const h = r.hist;
      h.forEach((seg, i) => {
        const end = i + 1 < h.length ? h[i + 1].at : now;
        if (end >= now - past) add(laneOf(seg.control), r.id);
      });
      add(r.lane, r.id);
      if (r.next && r.next.where !== 'gate') add(r.next.lane, r.id);
    }
    const geom = {};
    let top = 0;
    for (const l of LANES) {
      const height = occ[l].length ? LANE_PAD * 2 + occ[l].length * this.slotH() : EMPTY;
      geom[l] = { top, height };
      top += height;
    }
    return { occ, geom, total: top };
  }

  /* ---- drawing -------------------------------------------------------- */

  build() {
    this._built = true;
    this.innerHTML = '<div class="ov-head">'
      + '<span class="ov-aside ov-head__name ov-authority__label"></span>'
      + '<span class="ov-aside ov-head__note ov-authority__rules"></span></div>'
      // `--reading`: dense hides an ordinary state box, and OPERATIONAL is an
      // ordinary tone, but the picture's mode is always printed (refusal 5).
      + '<div class="ov-state ov-state--badge ov-state--reading ov-authority__mode"><span class="ov-state__word ov-authority__modeword"></span></div>'
      + '<div class="ov-authority__stamp"></div>'
      + '<div class="ov-authority__board">'
      + '<div class="ov-authority__axis"><span class="ov-authority__axisfield"></span><span class="ov-authority__gatehead">ON TRIGGER</span></div>'
      + '<div class="ov-authority__lanes"></div>'
      + '<div class="ov-authority__field">'
      + '<div class="ov-authority__bands"></div>'
      + '<svg class="ov-authority__svg" preserveAspectRatio="none" aria-hidden="true"><g class="ov-authority__tracks"></g></svg>'
      + '<div class="ov-authority__now" aria-hidden="true"></div>'
      + '<div class="ov-authority__systems"></div></div>'
      + '<div class="ov-authority__gates"></div>'
      + '</div>'
      + '<div class="ov-authority__foot"></div>'
      + '<span class="ov-authority__say" aria-live="polite"></span>';
    const q = (c) => this.querySelector(`.ov-authority__${c}`);
    this.$ = {
      label: q('label'), rules: q('rules'), mode: q('mode'), modeword: q('modeword'), stamp: q('stamp'),
      board: q('board'), axis: q('axisfield'), lanes: q('lanes'), field: q('field'), bands: q('bands'),
      svg: q('svg'), tracks: q('tracks'), now: q('now'), systems: q('systems'), gates: q('gates'),
      foot: q('foot'), say: q('say'),
    };
    this.setAttribute('role', 'group');
  }

  render() {
    if (!this._built) return;
    const now = OvAuthority.now();
    const pic = this._picture;
    const label = this.getAttribute('label') || 'AUTHORITY';
    setText(this.$.label, label);
    setText(this.$.rules, 'WHO HOLDS EACH SYSTEM, OVER TIME · NEXT ACTIONS AHEAD OF NOW');

    const mode = pic && Object.hasOwn(MODES, pic.mode) ? pic.mode : null;
    const maxAge = Number(this.getAttribute('max-age'));
    const stale = this._at !== null && Number.isFinite(maxAge) && maxAge > 0 && now - this._at > maxAge * 1000;
    // ok: operations. note: test or simulation. bad: no picture, or no mode.
    setAttr(this.$.mode, 'data-ov-tone', !pic || !mode ? 'bad' : mode === 'operational' ? 'ok' : 'note');
    setText(this.$.modeword, !pic ? 'NO PICTURE' : mode ? MODES[mode] : 'MODE NOT STATED');
    setAttr(this, 'data-ov-mode', mode);
    setText(this.$.stamp, stale ? `STALE · LAST REPORT ${span((now - this._at) / 1000)} AGO` : '');
    setAttr(this, 'data-ov-qualified', stale ? 'stale' : null);
    setAttr(this, 'data-ov-refusal', !pic ? 'unknown' : null);
    setAttr(this.$.board, 'data-ov-stale', stale ? 'yes' : null);
    this.$.board.hidden = !pic;

    // One layout read per draw, at most once a second, while on screen.
    const w = this.clientWidth;
    this._narrow = w > 0 && w < NARROW_W;
    setAttr(this, 'data-ov-narrow', this._narrow ? 'yes' : null);
    const rows = this.rows(now);
    const { occ, geom, total } = this.layout(rows, now);
    this.drawBoard(occ, geom, total, now);

    const key = rows.map((r) => r.id).join('|');
    if (key !== this._rowKey) {
      this._rowKey = key;
      this.$.systems.innerHTML = rows.map((r) => this.rowShell(r)).join('');
      this.$.gates.innerHTML = rows.map((r) => `<div class="ov-authority__gate" data-ov-gate="${esc(r.id)}"><i class="ov-authority__gatemark"></i><span class="ov-authority__gatetext"></span></div>`).join('');
      this._rows = new Map([...this.$.systems.children].map((el) => [el.dataset.ovSystem, el]));
    }
    let tracks = '';
    for (const r of rows) tracks += this.drawRow(this._rows.get(r.id), r, occ, geom, now);
    if (tracks !== this._tracks) { this._tracks = tracks; this.$.tracks.innerHTML = tracks; }

    const foot = [];
    if (this._malformed) foot.push(`${this._malformed} SYSTEM${this._malformed > 1 ? 'S' : ''} REFUSED: A SYSTEM NEEDS A UNIQUE ID`);
    if (pic && !rows.length) foot.push('NO SYSTEMS REPORTED');
    setText(this.$.foot, foot.join(' · '));

    const undeclared = rows.filter((r) => !r.control).map((r) => r.label);
    const unann = rows.filter((r) => r.unannounced).map((r) => r.label);
    setAttr(this, 'aria-label', !pic ? `${label}: no picture`
      : `${label}: ${mode ? MODES[mode].toLowerCase() : 'mode not stated'}, ${rows.length} systems`
        + (undeclared.length ? `, control undeclared on ${undeclared.join(', ').toLowerCase()}` : '')
        + (unann.length ? `, unannounced change on ${unann.join(', ').toLowerCase()}` : '')
        + (stale ? ', stale' : ''));
  }

  /* The lanes, their bands, the axis ticks and the NOW line. */
  drawBoard(occ, geom, total, now) {
    const lanes = LANES.map((l) => `<div class="ov-authority__lane" data-ov-lane="${l}" data-ov-empty="${occ[l].length ? 'no' : 'yes'}" style="block-size:${geom[l].height}px"><span>${LANE_WORD[l]}</span></div>`).join('');
    if (lanes !== this._lanesHtml) {
      this._lanesHtml = lanes;
      this.$.lanes.innerHTML = lanes;
      this.$.bands.innerHTML = LANES.map((l) => `<div class="ov-authority__band" data-ov-lane="${l}" style="inset-block-start:${geom[l].top}px;block-size:${geom[l].height}px"></div>`).join('');
      this.$.gates.style.blockSize = `${total}px`;
    }
    setStyle(this.$.field, 'block-size', `${total}px`);
    setAttr(this.$.svg, 'viewBox', `0 0 1000 ${total}`);
    setStyle(this.$.now, 'inset-inline-start', pct(X_NOW));
    const past = this.pastS();
    const ahead = this.aheadS();
    const ticks = [[0, `−${short(past)}`], [X_NOW, 'NOW'], [X_NOW + (1 - X_NOW) / 2, `+${short(ahead / 2)}`], [1, `+${short(ahead)}`]];
    const axis = ticks.map(([x, t]) => `<i style="inset-inline-start:${pct(x)}">${t}</i>`).join('');
    if (axis !== this._axisHtml) { this._axisHtml = axis; this.$.axis.innerHTML = axis; }
  }

  rowShell(r) {
    return `<div class="ov-authority__system" data-ov-system="${esc(r.id)}">`
      + '<div class="ov-authority__tag">'
      + '<span class="ov-authority__name"></span>'
      + '<span class="ov-authority__control"></span>'
      + '<span class="ov-authority__by"></span></div>'
      + '<div class="ov-authority__modes">'
      + '<span class="ov-authority__cell ov-authority__active"><b></b></span>'
      + '<span class="ov-authority__cell ov-authority__armed"><b></b></span></div>'
      + '<div class="ov-authority__sub">'
      + '<span class="ov-aside ov-authority__level"></span>'
      + '<span class="ov-authority__state"></span>'
      + '<span class="ov-authority__change"></span></div>'
      + '<div class="ov-authority__next"><i class="ov-authority__mark"></i><span class="ov-authority__owner"></span>'
      + '<span class="ov-authority__action"></span><span class="ov-authority__when"></span></div>'
      + '</div>';
  }

  /* Places a system's labels and returns its SVG: bars, steps, stubs. */
  drawRow(el, r, occ, geom, now) {
    const q = (c) => el.querySelector(`.ov-authority__${c}`);
    // Offsets inside a slot: wide, the name and the modes share the top line
    // either side of NOW; narrow, each takes its own line from the left.
    const O = this._narrow ? { modes: 12, bar: 30, sub: 38, next: 46 } : { modes: 0, bar: 17, sub: 22, next: 22 };
    const slotY = (lane) => geom[lane].top + LANE_PAD + Math.max(0, occ[lane].indexOf(r.id)) * this.slotH();
    const barY = (lane) => slotY(lane) + O.bar;
    setAttr(el, 'data-ov-control', r.control || 'undeclared');
    setAttr(el, 'data-ov-lane', r.lane);
    setAttr(el, 'data-ov-changed', r.box ? 'yes' : null);
    setAttr(el, 'data-ov-unannounced', r.unannounced ? 'yes' : null);
    setAttr(el, 'data-ov-mode-fault', r.modeFault ? 'yes' : null);

    // Top of the slot: name and controller behind NOW, modes ahead of it.
    const top = slotY(r.lane);
    setStyle(q('tag'), 'inset-block-start', `${top}px`);
    setStyle(q('modes'), 'inset-block-start', `${top + O.modes}px`);
    setStyle(q('sub'), 'inset-block-start', `${top + O.sub}px`);
    setText(q('name'), r.label);
    setText(q('control'), r.control ? CONTROL[r.control] : 'UNDECLARED');
    setText(q('by'), r.control && r.control !== 'auto' && r.by?.name ? `· ${String(r.by.name).toUpperCase()}` : '');
    setText(q('level'), r.level ? `LEVEL ${LEVEL[r.level]}` : 'LEVEL NOT STATED');
    setText(q('state'), r.modeFault ? `REFUSED · ${r.modeFault}` : r.state ? STATE[r.state] : 'STATE NOT STATED');

    // The mode annunciator: selected is never shown as armed.
    setText(q('active').querySelector('b'), r.active || 'NO MODE');
    const armedCell = q('armed');
    const armed = r.armed || (r.selected ? `${r.selected} SELECTED, NOT ARMED` : '—');
    // The arrow ahead of an armed mode is drawn by CSS, so the words stay
    // exactly the refusal, for the gate and for a screen reader.
    setText(armedCell.querySelector('b'), r.armed || r.selected ? armed : '');
    setAttr(armedCell, 'data-ov-selected-only', !r.armed && r.selected ? 'yes' : null);

    let change = '';
    const what = (c) => (c.what === 'control' ? 'CONTROL' : 'MODE');
    if (r.unannounced) {
      change = r.unannounced.map((c) => `UNANNOUNCED ${what(c)} CHANGE · FROM ${c.from} TO ${c.to} · NOT ACKNOWLEDGED`).join(' / ');
    } else if (r.box) {
      change = r.box.map((c) => (c.reverted ? `REVERTED FROM ${c.from}` : `${what(c)} FROM ${c.from}`)).join(' · ');
    }
    setText(q('change'), change);
    setAttr(q('change'), 'data-ov-tone', r.unannounced ? 'bad' : r.box?.some((c) => c.reverted) ? 'note' : r.box ? 'ok' : null);

    // The bars: each reported stretch of control, solid, in its lane.
    const X = (f) => f1(Math.max(0, Math.min(1, f)) * 1000);
    const cls = (c) => (c ? c : 'undeclared');
    let svg = '';
    r.hist.forEach((seg, i) => {
      const end = i + 1 < r.hist.length ? r.hist[i + 1].at : now;
      const x0 = this.xOf(seg.at, now);
      const x1 = this.xOf(end, now);
      if (x1 <= 0) return;
      const y = f1(barY(laneOf(seg.control)));
      svg += `<path class="ov-authority__bar" data-ov-control="${cls(seg.control)}"${r.modeFault ? ' data-ov-refused="yes"' : ''} d="M${X(x0)} ${y}H${X(x1)}"/>`;
      if (i > 0 && x0 > 0) {
        const from = f1(barY(laneOf(r.hist[i - 1].control)));
        // `data-ov-step-of`, not `data-ov-system`: the SVG comes before the
        // labels, so sharing the system hook made its first match a path.
        svg += `<path class="ov-authority__step" data-ov-step-of="${esc(r.id)}" data-ov-announced="${seg.announced ? 'yes' : 'no'}" d="M${X(x0)} ${from}V${y}"/>`;
      }
    });
    // Ahead of NOW is not known: a thin dotted continuation, not a bar.
    const yNow = f1(barY(r.lane));
    svg += `<path class="ov-authority__ahead" d="M${X(X_NOW)} ${yNow}H1000"/>`;
    if (r.armed || r.selected) {
      svg += `<path class="ov-authority__stub" data-ov-selected-only="${r.armed ? 'no' : 'yes'}" d="M${X(X_NOW)} ${yNow}H${X(X_NOW + 0.1)}"/>`;
    }

    // The next action: on the axis, pinned at NOW, or in the trigger column.
    const nx = r.next;
    const next = q('next');
    const gate = this.$.gates.querySelector(`[data-ov-gate="${CSS.escape(r.id)}"]`);
    setAttr(next, 'data-ov-tone', nx ? nx.tone : null);
    setAttr(next, 'data-ov-where', nx ? nx.where : 'absent');
    setText(q('owner'), nx ? (nx.owner ? OWNER[nx.owner] : 'OWNER NOT STATED') : '');
    setText(q('action'), nx ? nx.action : '');
    setText(q('when'), nx ? nx.when : 'NO NEXT ACTION STATED');
    if (nx && nx.where !== 'gate') {
      const lane = nx.lane;
      const x = nx.where === 'time' ? nx.x : X_NOW;
      setAttr(next, 'data-ov-lane', lane);
      setStyle(next, 'inset-block-start', `${slotY(lane) + O.next}px`);
      setStyle(next, 'inset-inline-start', pct(nx.where === 'none' ? X_NOW : x));
      // Near the right edge the words end at the marker instead of starting
      // there, or a narrow field clipped them to the owner alone ("CREW B").
      setAttr(next, 'data-ov-flip', nx.where === 'time' && x > 0.62 ? 'yes' : null);
      if (nx.where === 'now' && nx.dueX !== null) {
        svg += `<path class="ov-authority__overdue" d="M${X(nx.dueX)} ${f1(barY(lane))}H${X(X_NOW)}"/>`;
      }
    } else {
      setAttr(next, 'data-ov-lane', null);
      setStyle(next, 'inset-block-start', `${top + O.next}px`);
      setStyle(next, 'inset-inline-start', pct(X_NOW));
    }
    if (gate) {
      const inGate = nx && (nx.where === 'gate' || nx.inhibited);
      gate.hidden = !inGate;
      setAttr(gate, 'data-ov-inhibited', nx?.inhibited ? 'yes' : null);
      setStyle(gate, 'inset-block-start', `${top}px`);
      setText(gate.querySelector('.ov-authority__gatetext'), !inGate ? ''
        : nx.inhibited ? `${nx.trigger} · INHIBITED` : `${nx.trigger} › ${nx.action}`);
      // In the column, the marker says what waits; at NOW it says what will run.
      // No next action is not a refusal, so it draws nothing on the board:
      // written at NOW it sat on top of another system's lines.
      next.hidden = !nx || nx.where === 'gate';
    }
    return svg;
  }

  /* Everything said in one task is joined and said once. */
  say(text) {
    const region = this.$?.say;
    if (!region) return;
    (region._ovSay ||= []).push(text);
    if (region._ovSay.length > 1) return;
    queueMicrotask(() => {
      const all = region._ovSay;
      region._ovSay = [];
      region.textContent = '';
      region.textContent = all.join('. ');
    });
  }
}

define('ov-authority', OvAuthority);

export { OvAuthority };
